    const x1 = 100 + Math.cos(angle) * 80;
    const y1 = 100 + Math.sin(angle) * 80;
    const x2 = 100 + Math.cos(angle) * 150;
    const y2 = 100 + Math.sin(angle) * 150;

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.lineWidth = 8;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#333';
    ctx.stroke();

    // Tentacle tip
