// Draw spiral
function drawSpiral(x, y, size, angle, depth) {
    if (depth > 0) {
        // Draw spiral segment
        ctx.fillStyle = C2;
        ctx.globalAlpha = 0.7;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + size * Math.cos(angle), y - size * Math.sin(angle));
        ctx.strokeStyle = C2;
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.stroke();

        // Recursive call for next segment
        drawSpiral(
            x + size * Math.cos(angle),
            y - size * Math.sin(angle),
            size * 0.8,
            angle + Math.PI / 4,
            depth - 1
        );
    }
}

